use axum::{
    Router,
    extract::Path,
    http::{StatusCode, header},
    response::{IntoResponse, Response},
    routing::get,
};

/// Every file in the built `webui/dist/assets`, generated by `build.rs`.
static ASSETS: &[(&str, &[u8])] = include!(concat!(env!("OUT_DIR"), "/webui_assets.rs"));

fn content_type(name: &str) -> &'static str {
    match name.rsplit_once('.').map(|(_, ext)| ext) {
        Some("js" | "mjs") => "text/javascript; charset=utf-8",
        Some("css") => "text/css; charset=utf-8",
        Some("svg") => "image/svg+xml",
        Some("json" | "map") => "application/json",
        Some("png") => "image/png",
        Some("woff2") => "font/woff2",
        Some("woff") => "font/woff",
        _ => "application/octet-stream",
    }
}

/// The entry files keep fixed names across builds, so a cached copy could
/// point at chunks a new deploy no longer has: make browsers revalidate them.
/// Everything else Vite emits is content-hashed and safe to cache forever.
fn cache_control(name: &str) -> &'static str {
    match name {
        "index.js" | "index.css" | "logo.svg" => "no-cache",
        _ => "public, max-age=31536000, immutable",
    }
}

async fn serve_asset(Path(name): Path<String>) -> Response {
    match ASSETS.iter().find(|(n, _)| *n == name) {
        Some((n, body)) => (
            [
                (header::CONTENT_TYPE, content_type(n)),
                (header::CACHE_CONTROL, cache_control(n)),
            ],
            *body,
        )
            .into_response(),
        None => StatusCode::NOT_FOUND.into_response(),
    }
}

pub fn make_webui_router() -> Router {
    Router::new()
        .route(
            "/",
            get(|| async {
                (
                    [
                        (header::CONTENT_TYPE, "text/html; charset=utf-8"),
                        (header::CACHE_CONTROL, "no-cache"),
                    ],
                    include_str!("../../webui/dist/index.html"),
                )
            }),
        )
        .route("/assets/{name}", get(serve_asset))
}

#[cfg(test)]
mod tests {
    use super::*;
    use axum::body::Body;
    use axum::http::Request;
    use tower::ServiceExt;

    fn entry_js() -> &'static str {
        let (_, body) = ASSETS
            .iter()
            .find(|(n, _)| *n == "index.js")
            .expect("index.js embedded");
        std::str::from_utf8(body).unwrap()
    }

    /// Relative `./Name-hash.js` chunk references in the entry bundle.
    fn chunk_refs(js: &str) -> Vec<String> {
        let mut out = Vec::new();
        for quote in ['"', '\'', '`'] {
            let marker = format!("{quote}./");
            let mut rest = js;
            while let Some(i) = rest.find(&marker) {
                rest = &rest[i + marker.len()..];
                if let Some(end) = rest.find(quote) {
                    let name = &rest[..end];
                    if name.ends_with(".js") && !name.contains('/') {
                        out.push(name.to_string());
                    }
                }
            }
        }
        out.sort();
        out.dedup();
        out
    }

    async fn get(path: &str) -> Response {
        make_webui_router()
            .oneshot(Request::get(path).body(Body::empty()).unwrap())
            .await
            .unwrap()
    }

    #[tokio::test]
    async fn every_dynamic_chunk_of_the_entry_is_served_as_javascript() {
        let chunks = chunk_refs(entry_js());
        for page in ["RSSPage-", "IndexarrBrowse-"] {
            assert!(
                chunks.iter().any(|c| c.starts_with(page)),
                "no {page}*.js chunk referenced by index.js: {chunks:?}"
            );
        }
        for chunk in &chunks {
            let resp = get(&format!("/assets/{chunk}")).await;
            assert_eq!(resp.status(), StatusCode::OK, "{chunk}");
            let ct = resp.headers()[header::CONTENT_TYPE].to_str().unwrap();
            assert!(ct.starts_with("text/javascript"), "{chunk}: {ct}");
        }
    }

    #[tokio::test]
    async fn entry_is_revalidated_and_unknown_assets_404() {
        for path in ["/", "/assets/index.js", "/assets/index.css"] {
            let resp = get(path).await;
            assert_eq!(resp.status(), StatusCode::OK, "{path}");
            assert_eq!(resp.headers()[header::CACHE_CONTROL], "no-cache", "{path}");
        }
        assert_eq!(get("/assets/nope.js").await.status(), StatusCode::NOT_FOUND);
    }
}
